INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'tshwane-double-column-ballot-70-parties-2026-10-09',
  'Tshwane ballot needs double column with 70 parties in PR race',
  'Community', '2026-10-09', 'Rekord', 'https://www.citizen.co.za/rekord/news-headlines/2026/10/09/tshwane-2026-election-79-parties-to-compete-on-crowded-ballot/',
  'The IEC says Tshwane''s ballot paper will use a double-column layout because 70 parties are contesting proportional representation seats in the 4 November election.',
  'Tshwane will have one of the most crowded ballot papers in the country for the 4 November local government elections, after the Electoral Commission (IEC) certified 70 parties to contest proportional representation (PR) seats in the metro. Because that number is well above the 48-party threshold the IEC uses, Tshwane''s PR ballot will be printed in a double-column format instead of the usual single column, so that every party''s name and logo still fits legibly.

The same double-column rule applies to any ward where more than 48 candidates are standing. Nationally, the IEC says it has certified 136,790 candidates to contest the elections, after disqualifying 5,096 during its review process.

For Tshwane residents, the practical effect is an unfamiliar-looking ballot paper at the polling station on election day. The Pretoria Chamber of Commerce and Industry has said whoever ends up running the city afterwards needs to prioritise stable infrastructure to keep investors interested, according to Rekord.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/rekord/news-headlines/2026/10/09/tshwane-2026-election-79-parties-to-compete-on-crowded-ballot/", "https://www.ewn.co.za/iec-confirms-double-column-ballot-papers-for-high-contestation-metros-on-november-4th/", "https://www.gov.za/news/media-statements/electoral-commission-certifies-136-790-candidates-contest-2026-local"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'riet-river-sewage-centurion-18-years-2026-10-09',
  'Sewage still flowing into Riet River after 18 years, Centurion residents say',
  'Utilities', '2026-10-09', 'Rekord', 'https://www.citizen.co.za/rekord/news-headlines/2026/10/09/tshwane-metro-plans-sewer-repairs-as-centurion-residents-battle-18-year-pollution-crisis/',
  'Thatchfield Estate residents in Centurion say sewage has polluted the Riet River for 18 years, and the City of Tshwane says repairs are waiting on approvals.',
  'Residents of the Thatchfield Estate in Centurion say sewage has been entering the Riet River for about 18 years, according to estate manager Mossie Mostert. Ward councillor Alta de Kock has linked the pollution to wastewater reaching the river, together with rubbish piling up along its banks, and the Democratic Alliance''s Gauteng caucus says the matter has also been reported this year to the municipality''s nature conservation officials.

Mostert said the odour reaches around 50 nearby homes, leaving residents reluctant to open windows and relying instead on air conditioning, and that people can no longer safely enter the water. The DA''s Gauteng spokesperson on the environment, Leanne de Jager, wants the municipality to track down and fix whatever is causing the pollution, place traps to catch litter before it reaches the water, and run a public education drive on dumping near rivers.

The City of Tshwane told Rekord that planning and design work is complete for several sewer repair projects in the area, including fixing a collapsed outfall pipe and reconstructing a damaged sewer line, but that implementation is waiting on environmental approvals and the appointment of contractors. In the meantime, the city says it carries out monthly inspections and water-quality monitoring and responds to reported faults, and crews recently cleared a blockage near the river.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/rekord/news-headlines/2026/10/09/tshwane-metro-plans-sewer-repairs-as-centurion-residents-battle-18-year-pollution-crisis/", "https://dagpl.substack.com/p/raw-sewage-continues-to-flow-into-510"]',
  'agent'
);
